import React, { useEffect, useRef, useState } from "react";
import ForceGraph2D from "react-force-graph";

export default function GraphView() {
  const [data, setData] = useState({ nodes: [], links: [] });

  useEffect(() => {
    const fetchData = () => {
      fetch("http://localhost:5000/api/graph")
        .then((res) => res.json())
        .then(setData);
    };

    fetchData();
    const interval = setInterval(fetchData, 4000); // refresh every 4s

    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ height: "100vh" }}>
      <ForceGraph2D
        graphData={data}
        nodeAutoColorBy="type"
        nodeCanvasObject={(node, ctx, globalScale) => {
          const label = node.id.slice(0, 6);
          const fontSize = 12 / globalScale;
          ctx.font = `${fontSize}px Sans-Serif`;
          ctx.fillStyle = node.type === "node" ? "black" : "blue";
          ctx.beginPath();
          ctx.arc(
            node.x,
            node.y,
            node.type === "node" ? 10 : 5,
            0,
            2 * Math.PI,
          );
          ctx.fill();
          ctx.fillText(label, node.x + 10, node.y + 3);
        }}
        linkDirectionalParticles={1}
        linkDirectionalParticleWidth={(link) => 2}
      />
    </div>
  );
}
